/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { AngularMomentumScreen } from "../../src/angular-momentum/AngularMomentumScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { OrbitalsScreen } from "../../src/orbitals/OrbitalsScreen.js";
import { OscillatorScreen } from "../../src/oscillator/OscillatorScreen.js";
import { QuantumAtom3DPreferencesModel } from "../../src/preferences/QuantumAtom3DPreferencesModel.js";
import QuantumAtom3DColors from "../../src/QuantumAtom3DColors.js";
import { SuperpositionScreen } from "../../src/superposition/SuperpositionScreen.js";
import { ZeemanScreen } from "../../src/zeeman/ZeemanScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from quantumAtom3DQueryParameters.
  const simPreferences = new QuantumAtom3DPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new OrbitalsScreen({
      preferences: simPreferences,
      name: stringManager.getScreenNames().orbitalsStringProperty,
      tandem: Tandem.ROOT.createTandem("orbitalsScreen"),
      backgroundColorProperty: QuantumAtom3DColors.backgroundColorProperty,
    }),
    new SuperpositionScreen({
      preferences: simPreferences,
      name: stringManager.getScreenNames().superpositionStringProperty,
      tandem: Tandem.ROOT.createTandem("superpositionScreen"),
      backgroundColorProperty: QuantumAtom3DColors.backgroundColorProperty,
    }),
    new AngularMomentumScreen({
      name: stringManager.getScreenNames().angularMomentumStringProperty,
      tandem: Tandem.ROOT.createTandem("angularMomentumScreen"),
      backgroundColorProperty: QuantumAtom3DColors.backgroundColorProperty,
    }),
    new ZeemanScreen({
      name: stringManager.getScreenNames().zeemanStringProperty,
      tandem: Tandem.ROOT.createTandem("zeemanScreen"),
      backgroundColorProperty: QuantumAtom3DColors.backgroundColorProperty,
    }),
    new OscillatorScreen({
      preferences: simPreferences,
      name: stringManager.getScreenNames().oscillatorStringProperty,
      tandem: Tandem.ROOT.createTandem("oscillatorScreen"),
      backgroundColorProperty: QuantumAtom3DColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { QuantumAtom3DColors, stringManager, simPreferences } };
}

let built: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    built = buildSim();
    return built.screens;
  },
  tracked: () => built?.tracked ?? {},
});
